    private IpCard themeCard(String slug, String title, String category, int heat, String source, String tags, String reason, String direction) {
        return new IpCard(slug, title, category, heat, source, tags,
                "每个主题已随机生成 10 张角色卡，采用独立卡牌美术风格。",
                direction, reason, res("theme_" + slug), roleSet(slug));
    }

    private int[] roleSet(String slug) {
        int[] roles = new int[10];
        for (int i = 0; i < roles.length; i++) {
            roles[i] = res("role_" + slug + "_" + String.format(Locale.ROOT, "%02d", i + 1));
        }
        return roles;
    }

    private int[] mistCast() {
        return new int[]{
                R.drawable.mist_role_01,
                R.drawable.mist_role_02,
                R.drawable.mist_role_03,
                R.drawable.mist_role_04,
                R.drawable.mist_role_05,
                R.drawable.mist_role_06,
                R.drawable.mist_role_07,
                R.drawable.mist_role_08,
                R.drawable.mist_role_09,
                R.drawable.mist_role_10
        };
    }

    private int res(String name) {
        return getResources().getIdentifier(name, "drawable", getPackageName());
    }

