func isolateCard(in source: CGImage) -> CGImage? {
    let width = source.width
    let height = source.height
    guard let data = source.dataProvider?.data,
          let bytes = CFDataGetBytePtr(data) else {
        return nil
    }

    let bytesPerPixel = max(1, source.bitsPerPixel / 8)
    let bytesPerRow = source.bytesPerRow
    var minX = width
    var minY = height
    var maxX = 0
    var maxY = 0

    for y in 0..<height {
        for x in 0..<width {
            let offset = y * bytesPerRow + x * bytesPerPixel
            let r = Int(bytes[offset])
            let g = Int(bytes[offset + min(1, bytesPerPixel - 1)])
            let b = Int(bytes[offset + min(2, bytesPerPixel - 1)])
            let brightness = r + g + b
            let colored = brightness > 42 && max(r, g, b) - min(r, g, b) > 5
            if colored {
                minX = min(minX, x)
                minY = min(minY, y)
                maxX = max(maxX, x)
                maxY = max(maxY, y)
            }
