import AppKit
import Foundation

let args = CommandLine.arguments.dropFirst()
let files = args.map { URL(fileURLWithPath: $0) }
let thumbW = 120
let thumbH = 180
let labelH = 22
let gap = 8
let columns = 5
let rows = Int(ceil(Double(files.count) / Double(columns)))
let sheetW = columns * thumbW + (columns + 1) * gap
let sheetH = rows * (thumbH + labelH) + (rows + 1) * gap

let image = NSImage(size: NSSize(width: sheetW, height: sheetH))
image.lockFocus()
NSColor.black.setFill()
NSRect(x: 0, y: 0, width: sheetW, height: sheetH).fill()

let attrs: [NSAttributedString.Key: Any] = [
    .font: NSFont.monospacedDigitSystemFont(ofSize: 12, weight: .bold),
    .foregroundColor: NSColor.white
]

for (idx, file) in files.enumerated() {
    guard let src = NSImage(contentsOf: file) else { continue }
    let col = idx % columns
    let row = idx / columns
    let x = gap + col * (thumbW + gap)
    let yTop = gap + row * (thumbH + labelH + gap)
    let y = sheetH - yTop - thumbH
    let drawRect = NSRect(x: x, y: y, width: thumbW, height: thumbH)
    src.draw(in: drawRect, from: .zero, operation: .sourceOver, fraction: 1.0, respectFlipped: true, hints: [.interpolation: NSImageInterpolation.high])
    "\(idx)".draw(in: NSRect(x: x + 4, y: y - labelH, width: thumbW - 8, height: labelH), withAttributes: attrs)
}

image.unlockFocus()

guard let tiff = image.tiffRepresentation,
      let rep = NSBitmapImageRep(data: tiff),
      let png = rep.representation(using: .png, properties: [:]) else {
    fatalError("Could not render sheet")
}

try png.write(to: URL(fileURLWithPath: "/private/tmp/generated_contact_sheet.png"))
try files.enumerated().map { "\($0.offset)\t\($0.element.path)" }.joined(separator: "\n").write(toFile: "/private/tmp/generated_contact_sheet.txt", atomically: true, encoding: .utf8)

