    private boolean handleFeedTouch(MotionEvent event) {
        if (event.getAction() == MotionEvent.ACTION_DOWN) {
            touchDownY = event.getY();
            touchDownX = event.getX();
            return true;
        }
        if (event.getAction() == MotionEvent.ACTION_UP) {
            float deltaY = event.getY() - touchDownY;
            float deltaX = event.getX() - touchDownX;
            if (Math.abs(deltaY) > dp(70) && Math.abs(deltaY) > Math.abs(deltaX)) {
                moveFeed(deltaY < 0 ? 1 : -1);
                return true;
            }
            if (Math.abs(deltaY) < dp(18) && Math.abs(deltaX) < dp(18)) {
                openCurrentCard();
            }
            return true;
        }
        return true;
    }

    private void openCurrentCard() {
        if (!visibleCards.isEmpty() && currentIndex < visibleCards.size()) {
            showDetails(visibleCards.get(currentIndex));
        }
    }

    private List<IpCard> filteredCards() {
        String query = search == null ? "" : search.getText().toString().trim().toLowerCase(Locale.ROOT);
        List<IpCard> visible = new ArrayList<>();
        for (IpCard card : cards) {
            if (!"全部".equals(selectedCategory) && !selectedCategory.equals(card.category)) {
                continue;
            }
            String searchable = (card.title + card.category + card.source + card.tags + card.summary + card.direction + card.reason).toLowerCase(Locale.ROOT);
            if (!query.isEmpty() && !searchable.contains(query)) {
                continue;
            }
            visible.add(card);
        }
        return visible;

