    private void showPurchaseScopeMenu(View anchor) {
        persistAddressDraft();
        PopupMenu menu = new PopupMenu(this, anchor);
        menu.getMenu().add("全部卡组");
        menu.getMenu().add("收藏卡组");
        menu.setOnMenuItemClickListener(item -> {
            purchaseCollectedOnly = "收藏卡组".contentEquals(item.getTitle());
            ensureSelectedPurchaseCardAvailable();
            renderFeed();
            return true;
        });
        menu.show();
    }

    private View purchaseCardPicker(List<IpCard> purchaseOptions) {
