        LinearLayout row = new LinearLayout(this);
        row.setOrientation(LinearLayout.HORIZONTAL);
        row.setPadding(0, 0, dp(4), 0);
        scroll.addView(row);
        for (IpCard card : purchaseOptions) {
            row.addView(purchaseCardOption(card), rightMargin(dp(10)));
        }
        return scroll;
    }

